-- My Recovery Passport client-safe projection layer
create table if not exists public.recovery_passport_reflections (id uuid primary key default gen_random_uuid(),client_id uuid not null references public.clients(id) on delete cascade,journey_id uuid references public.recovery_journeys(id) on delete cascade,prompt_key text,reflection_text text not null check(char_length(reflection_text)<=4000),visibility text not null default 'PRIVATE_TO_ME' check(visibility in ('PRIVATE_TO_ME','SHARED_WITH_CARE_TEAM')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.passport_visibility_rules (id uuid primary key default gen_random_uuid(),resource_type text not null,event_key text,visibility text not null default 'STAFF_ONLY' check(visibility in ('CLIENT_VISIBLE','CLIENT_VISIBLE_AFTER_REVIEW','STAFF_ONLY','CLINICAL_RESTRICTED','PRIVATE_CLIENT','FAMILY_VISIBLE_WITH_CONSENT')),active boolean not null default true,description text,created_at timestamptz not null default now(),unique(resource_type,event_key));
create table if not exists public.passport_projection_events (id uuid primary key default gen_random_uuid(),client_id uuid not null references public.clients(id) on delete cascade,journey_id uuid references public.recovery_journeys(id) on delete cascade,source_type text not null,source_id text,event_key text not null,visibility text not null default 'STAFF_ONLY',verified_at timestamptz,verified_by uuid,client_safe_payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists idx_passport_reflections_client_created on public.recovery_passport_reflections(client_id,created_at desc);create index if not exists idx_passport_projection_client_created on public.passport_projection_events(client_id,created_at desc);alter table public.recovery_passport_reflections enable row level security;alter table public.passport_visibility_rules enable row level security;alter table public.passport_projection_events enable row level security;
create policy passport_reflections_client_select on public.recovery_passport_reflections for select using(client_id in(select client_id from public.profiles where auth_user_id=auth.uid() and is_active=true and role::text='client'));create policy passport_reflections_client_insert on public.recovery_passport_reflections for insert with check(client_id in(select client_id from public.profiles where auth_user_id=auth.uid() and is_active=true and role::text='client'));create policy passport_reflections_client_update on public.recovery_passport_reflections for update using(client_id in(select client_id from public.profiles where auth_user_id=auth.uid() and is_active=true and role::text='client')) with check(client_id in(select client_id from public.profiles where auth_user_id=auth.uid() and is_active=true and role::text='client'));create policy passport_projection_client_select on public.passport_projection_events for select using(visibility='CLIENT_VISIBLE' and verified_at is not null and client_id in(select client_id from public.profiles where auth_user_id=auth.uid() and is_active=true and role::text='client'));